 function acknowledgeOperation(id){const operation=byId('operations',id);if(!operation||!operation.source_changed||!canEdit())return;form('Acknowledge changed source', '<p class="full notice">Booked or completed work is protected. This acknowledges the changed export while keeping the existing approved scope.</p><p class="full"><strong>'+e(operation.description)+'</strong><br>'+e(stageNames[operation.stage_code])+' · '+e(operation.estimated_hours)+' hours · Parts '+e(operation.parts_required?'required':'not required')+'</p><details class="full source-evidence" open><summary>Latest export evidence</summary><pre>'+e(JSON.stringify(operation.observed_source_row||operation.source_row,null,2))+'</pre></details>'+checkField('confirmed','I reviewed the changed source and confirm the existing approved scope remains correct',false),values=>{if(!values.has('confirmed'))throw new Error('Review the source change and confirm the retained scope.');return {stage_code:operation.stage_code,estimated_hours:operation.estimated_hours,parts_required:operation.parts_required};},{id,version:operation.version,action:'operation'});}
 function openOperation(id){const operation=byId('operations',id);if(!operation||!canEdit())return;const fields=selectField('stage_code','Reviewed work stage',Object.entries(stageNames),operation.stage_code)+field('estimated_hours','Approved hours','number',operation.estimated_hours,'step="0.01" min="0" max="999.99" required')+selectField('parts_required','Parts required',[['','Unknown — review required'],['yes','Yes'],['no','No']],operation.parts_required===null?'':operation.parts_required?'yes':'no')+'<p class="full field-help">Original source: '+e(operation.description)+' · '+e(operation.source_estimated_hours??'Unknown')+' hours. Booked or completed work is protected.</p>';form('Review operation',fields,values=>{const hours=Number(values.get('estimated_hours')),parts=values.get('parts_required');if(!parts)throw new Error('Confirm whether parts are required.');if(!Number.isFinite(hours)||hours<0)throw new Error('Enter valid approved hours.');return {stage_code:values.get('stage_code'),estimated_hours:hours,parts_required:parts==='yes'};},{id,version:operation.version,action:'operation'});}
