 document.addEventListener('change',event=>{const target=event.target;if(target.dataset.importDealer&&state.import){const codes=new Set(state.import.dealers||[]);if(target.checked)codes.add(target.dataset.importDealer);else codes.delete(target.dataset.importDealer);state.import.dealers=[...codes];state.import.preview=null;state.importSequence++;}else if(target.dataset.selectJob){if(target.checked)state.selected.add(target.dataset.selectJob);else state.selected.delete(target.dataset.selectJob);render();}else if(target.id==='nuvu-file'&&target.files?.[0])void loadFile(target.files[0]);else if(target.dataset.mapField&&state.import){state.import.mapping[target.dataset.mapField]=target.value;state.import.preview=null;state.importSequence++;}else if(target.id==='nuvu-sheet'&&state.import){state.import.sheet=target.value;state.importSequence++;rebuildImport();}else if(target.id==='nuvu-header'&&state.import){state.import.headerRow=Number(target.value);state.importSequence++;rebuildImport();}else if(target.id==='nuvu-delimiter'&&state.import){state.import.delimiter=target.value==='comma'?',':target.value==='semicolon'?';':'\t';state.importSequence++;rebuildImport();}});
